import os, re
def load():
    d=os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        import glob
        latest = glob.glob('/tmp/rlm_default/*/.jsonl')
        latest.sort(key=os.path.getmtime, reverse=True)
        if latest:
            d = os.path.dirname(os.path.dirname(latest[0]))
            session_name = os.path.basename(os.path.dirname(latest[0]))
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = t[m.end():].split('\n')[:h]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r.split()] for r in rows]
    return G

G = load()
print("Data loaded:")
for k, v in G.items():
    print(f"{k}: shape={len(v)}x{len(v[0])}")

